/// <summary>
///    Finds the specified record in the <c>AVAPriceIncreaseLine</c> table.
/// </summary>
/// <param name="_recordId">
///    The record ID of the <c>AVAPriceIncreaseLine</c> record to find.
/// </param>
/// <param name="_recordId2">
///    The record ID2 of the <c>AVAPriceIncreaseLine</c> record to find.
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>AVAPriceIncreaseLine</c> table; otherwise, an empty record.
/// </returns>
public static AVAPriceIncreaseLine find( AVAPriceIncreaseSet    _recordId,
                                         KCS_GoodsId            _recordId2,
                                         boolean                _forUpdate = false)
{
    AVAPriceIncreaseLine record;

    if (    _recordId 
        &&  _recordId2  )
    {
        record.selectForUpdate(_forUpdate);

        select firstonly record
        index hint PriceIncreaseLineIdx
        where   record.PriceIncreaseSet == _recordId
            &&  record.KCS_GoodsId      == _recordId2;
    }
    return record;
}

/// <summary>
///     AVA <c>findOrCreate</c> method.
/// </summary>
/// <param name="_recordId">
///    The record ID of the <c>AVAPriceIncreaseLine</c> record to find.
/// </param>
/// <param name="_recordId2">
///    The record ID2 of the <c>AVAPriceIncreaseLine</c> record to find.
/// </param>
/// <param name="_value">
///    The value of the <c>AVAPriceIncreasePercentage</c> record to find.
/// </param>
/// <returns>
///     <c>AVAPriceIncreaseLine</c> as return value
/// </returns>
public static AVAPriceIncreaseLine findOrCreate(AVAPriceIncreaseSet         _recordId,
                                                KCS_GoodsId                 _recordId2,
                                                AVAPriceIncreasePercentage  _value      = 0.0   )
{
    AVAPriceIncreaseLine record;

    if (    _recordId
        &&  _recordId2  )
    {
        record = AVAPriceIncreaseLine::find(_recordId, _recordId2);

        if(!record.RecId)
        {
            record.clear();
            record.PriceIncreaseSet         = _recordId;
            record.KCS_GoodsId              = _recordId2;
            record.PriceIncreasePercentage  = _value;
            record.insert();
        }
    }
    return record;
}

/// <summary>
///    Finds the specified record in the <c>AVAPriceIncreaseLine</c> table.
/// </summary>
/// <param name="_recordId">
///    The record ID of the <c>AVAPriceIncreaseLine</c> record to find.
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>AVAPriceIncreaseLine</c> table; otherwise, an empty record.
/// </returns>
public static AVAPriceIncreaseLine findByRecId( RecId   _recordId, 
                                                boolean _forUpdate = false)
{
    AVAPriceIncreaseLine record;

    if (_recordId)
    {
        record.selectForUpdate(_forUpdate);

        select firstonly record
        where record.RecId == _recordId;
    }
    return record;
}

